import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int mod = m;

        int[] dp = new int[n + 3];
        int[] sdp = new int[n + 3];

        dp[n] = 1;
        sdp[n] = 1;

        for (int x = n - 1; x > 0; x--) {
            dp[x] = (dp[x] + sdp[x + 1]) % mod;
            int z = 2;
            while (x * z <= n) {
                int l = x * z;
                int r = (x + 1) * z - 1;
                if (r > n) r = n;
                dp[x] = (dp[x] + sdp[l] - sdp[r + 1]) % mod;
                if (dp[x] < 0) {
                    dp[x] += mod;
                }
                z++;
            }
            sdp[x] = (sdp[x + 1] + dp[x]) % mod;
        }

        System.out.println(dp[1] % mod);
        sc.close();
    }
}
